select id, currency, tier_limits, element_at(tier_prices, 1) as entry_price, aggregate(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, slice(tier_limits, 1, 2) as first_two_limits, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps from price_tiers where currency != 'THB'
